import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { PORTABLE } from "@/scripts/skills/portable";

// skills/unchore-recipes is generated by `pnpm skills` — this fails when a recipe changed and the skill wasn't rebuilt.
describe("exported agent skill", () => {
  const md = readFileSync(path.resolve(__dirname, "../skills/unchore-recipes/SKILL.md"), "utf8");

  it("lists every portable recipe with its current catalog line", () => {
    expect(PORTABLE.length).toBeGreaterThan(0);
    for (const r of PORTABLE) expect(md).toContain(`\`${r.id}\` — ${r.catalog}`);
  });

  it("never ships recipes that need the member's AI or our browser", () => {
    expect(PORTABLE.every((r) => r.where === "server")).toBe(true);
    expect(md).not.toMatch(/`(ai_digest|reminder|danawa_lowest|google_flights)`/);
  });

  it("has the Agent Skills front matter", () => {
    expect(md).toMatch(/^---\nname: unchore-recipes\ndescription: .{20,1024}\n---\n/);
  });
});
